"""一次性入库：2026-10-02 第七轮（CKAN/DKAN 判据修正后的补漏批次）新增 636 条。

背景（2026-10-02）：前几批分类器判 CKAN 用的是 '"success": true'（带空格），而真实 CKAN 返回
'"success":true'（无空格），导致 700+ 个 CKAN 站被误判为普通 json200 而漏收。本轮用修正后的判据
（ckan_version 或 help+success 同时出现）重扫全部 22458 个探测结果，补回这些站。
- 实测证据：每个条目都返回真实 CKAN status_show JSON（site_title / extensions 列表）。
- 已与库内域名查重（76 条命中库内旧条目被跳过）。
注意：本轮按用户要求不执行 git 提交。
"""
